        content:
          '**Ce test n\'a pas fait l\'objet d\'un essai pratique par PromptQuorum sur une unité physique.** Il s\'appuie sur les spécifications publiées par le fabricant et des tests indépendants tiers, clairement distingués ci-dessous entre ce qui est confirmé et ce qui est estimé.',
